e": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "公式记错：如圆锥体积忘记乘1/3"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "相似比用错：面积比是相似比的平方，不是一次方"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "单位不统一：题目给的单位和公式要求的单位不一致"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "几何题需要熟记公式，建议整理一张公式卡片随身带。重点练习面积计算和最短路径问题。"}]}]}]}$$ AS jsonb), NULL, '数量关系-数学运算-几何问题的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "数学运算", "几何问题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_math_operation_geometry", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
